// Isolated native movement test entry point; never ship this function.
#define Generate_Mission_Starts SAM_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaigntraffic.h"
static CELL center;
static void Tile(int dx,int dy,bool open){CELL c=XY_Cell(Cell_X(center)+dx,Cell_Y(center)+dy);if(!Map.In_Radar(c))return;auto& m=Map[c];m.TType=TEMPLATE_CLEAR1;m.TIcon=0;m.Overlay=open?OVERLAY_NONE:OVERLAY_BRICK_WALL;m.OverlayData=0;m.Owner=HOUSE_GOOD;m.Recalc_Attributes();}
static void Setup(const std::string& dir){Reset(dir);Campaign_Traffic_Reset();center=Center();for(int i=Terrains.Count()-1;i>=0;--i)Terrains.Ptr(i)->Limbo();for(int y=-10;y<=10;++y)for(int x=-14;x<=14;++x)Tile(x,y,false);for(int x=-12;x<=12;++x)Tile(x,0,true);for(int y=-3;y<=-1;++y)for(int x=-5;x<=-3;++x)Tile(x,y,true);for(int y=-3;y<=3;++y)for(int x:{-12,-11,-10,10,11,12})Tile(x,y,true);PlayerPtr->Credits=1000000;PlayerPtr->Tiberium=0;}
static UnitClass* Tank(int x,int y=0){auto t=new UnitClass(UNIT_MTANK,HOUSE_GOOD);Check("place exact native tank cell",t->Unlimbo(Cell_Coord(XY_Cell(Cell_X(center)+x,Cell_Y(center)+y)),DIR_E));t->Assign_Mission(MISSION_GUARD);t->Commence();return t;}
static void Move(FootClass* t,int x,int y=0){t->Assign_Mission(MISSION_MOVE);t->Commence();t->Assign_Destination(::As_Target(XY_Cell(Cell_X(center)+x,Cell_Y(center)+y)));}
static void Tick(){++Frame;if(Frame%TICKS_PER_SECOND==0)Campaign_Traffic_AI();std::vector<TARGET> ids;for(int i=0;i<Units.Count();++i)if(!Units.Ptr(i)->IsInLimbo)ids.push_back(Units.Ptr(i)->As_Target());for(auto id:ids){auto u=As_Unit(id);if(u)u->AI();}ids.clear();for(int i=0;i<Infantry.Count();++i)if(!Infantry.Ptr(i)->IsInLimbo)ids.push_back(Infantry.Ptr(i)->As_Target());for(auto id:ids){auto f=As_Infantry(id);if(f)f->AI();}}
static bool InWall(FootClass* f){return Map[Coord_Cell(f->Coord)].Overlay==OVERLAY_BRICK_WALL;}
static void HeadOn(const std::string& dir,bool save){Setup(dir);auto a=Tank(-5),b=Tank(5);auto aid=a->As_Target(),bid=b->As_Target();Move(a,11);Move(b,-11);bool yielded=false,saved=false,overlap=false,wall=false;for(int tick=0;tick<3500;++tick){Tick();a=As_Unit(aid);b=As_Unit(bid);if(!a||!b){Check("both corridor tanks remain alive",false);break;}bool temp=a->SuspendedMission!=MISSION_NONE||b->SuspendedMission!=MISSION_NONE;yielded|=temp;overlap|=Coord_Cell(a->Coord)==Coord_Cell(b->Coord);wall|=InWall(a)||InWall(b);if(save&&temp&&!saved){Check("save during actual passing-bay yield",Save_Game((dir+"/traffic-yield.sav").c_str(),"NATIVE TRAFFIC YIELD"));Check("reload during actual passing-bay yield",Load_Game((dir+"/traffic-yield.sav").c_str()));saved=true;a=As_Unit(aid);b=As_Unit(bid);}if(Cell_X(Coord_Cell(a->Coord))>=Cell_X(center)+10&&Cell_X(Coord_Cell(b->Coord))<=Cell_X(center)-10)break;}
 std::printf("HEADON save=%d yielded=%d a=%d,%d b=%d,%d target=%u,%u\n",int(save),int(yielded),Cell_X(Coord_Cell(a->Coord))-Cell_X(center),Cell_Y(Coord_Cell(a->Coord))-Cell_Y(center),Cell_X(Coord_Cell(b->Coord))-Cell_X(center),Cell_Y(Coord_Cell(b->Coord))-Cell_Y(center),unsigned(a->NavCom),unsigned(b->NavCom));Check("opposing vehicles select a temporary passing bay",yielded);Check("both opposing vehicles actually traverse the single-lane corridor",Cell_X(Coord_Cell(a->Coord))>=Cell_X(center)+10&&Cell_X(Coord_Cell(b->Coord))<=Cell_X(center)-10);Check("traffic never overlaps vehicle cells or drives through walls",!overlap&&!wall);if(save)Check("passing-bay recovery survives save/load",saved&&a->SuspendedMission==MISSION_NONE&&b->SuspendedMission==MISSION_NONE);
}
static void WakeUp(const std::string& dir){Setup(dir);auto a=Tank(-1),b=Tank(0);auto id=b->As_Target();Move(a,0);TARGET goal=::As_Target(center);Check("nearby temporary occupant never discards a new move order",a->NavCom==goal);for(int tick=0;tick<80;++tick){++Frame;a->AI();}Check("blocked unit keeps its destination while waiting",a->NavCom==goal);delete b;Campaign_Traffic_Forget(id);for(int tick=0;tick<300&&Coord_Cell(a->Coord)!=center;++tick)Tick();Check("blocked unit wakes automatically after obstruction is removed",Coord_Cell(a->Coord)==center);}
static void StationaryYield(const std::string& dir){Setup(dir);auto a=Tank(-4),b=Tank(0);Move(a,8);bool yielded=false;for(int tick=0;tick<2000;++tick){Tick();yielded|=b->SuspendedMission!=MISSION_NONE;if(Cell_X(Coord_Cell(a->Coord))>=Cell_X(center)+7)break;}Check("idle friendly blocker vacates the corridor without collisions",!InWall(b)&&Coord_Cell(a->Coord)!=Coord_Cell(b->Coord));Check("moving vehicle passes the idle blocker",Cell_X(Coord_Cell(a->Coord))>=Cell_X(center)+7);Check("idle blocker retains its original guard mission after yield",b->Mission==MISSION_GUARD&&b->SuspendedMission==MISSION_NONE);}
static void Command(const std::string& dir){Setup(dir);auto a=Tank(-3),b=Tank(1);Move(a,9);Move(b,-9);for(int tick=0;tick<1500&&a->SuspendedMission==MISSION_NONE&&b->SuspendedMission==MISSION_NONE;++tick)Tick();auto yielded=a->SuspendedMission!=MISSION_NONE?a:b;Check("obtain an actual yielded vehicle",yielded->SuspendedMission!=MISSION_NONE);TARGET oldGoal=yielded->SuspendedNavCom;yielded->Assign_Mission(MISSION_STOP);yielded->Assign_Destination(TARGET_NONE);yielded->Commence();Check("explicit stop clears the old suspended move intent",yielded->SuspendedMission==MISSION_NONE&&yielded->NavCom==TARGET_NONE);for(int tick=0;tick<90;++tick)Tick();Check("recovery never resurrects the explicitly cancelled destination",yielded->NavCom!=oldGoal&&yielded->SuspendedNavCom!=oldGoal);}
static void InfantryWake(const std::string& dir){Setup(dir);auto blocker=Tank(0);auto inf=new InfantryClass(INFANTRY_E1,HOUSE_GOOD);Check("place infantry in the one-cell corridor",inf->Unlimbo(Cell_Coord(XY_Cell(Cell_X(center)-1,Cell_Y(center))),DIR_E));Move(inf,0);TARGET goal=::As_Target(center);for(int tick=0;tick<120;++tick){++Frame;inf->AI();}Check("infantry retains its nearby goal behind a friendly vehicle",inf->NavCom==goal);delete blocker;for(int tick=0;tick<300&&Coord_Cell(inf->Coord)!=center;++tick)Tick();Check("infantry automatically wakes once a blocked cell clears",Coord_Cell(inf->Coord)==center);}
static void Restrictions(const std::string& dir){Setup(dir);auto a=Tank(-1),b=Tank(0);Move(a,7);a->IsALoaner=true;Check("scripted transport-loaner movement is not retained by traffic",!Campaign_Traffic_Wait(a));a->IsALoaner=false;a->Assign_Mission(MISSION_ENTER);a->Commence();Check("repair and transport entry keeps native retry semantics",!Campaign_Traffic_Wait(a));a->Assign_Mission(MISSION_MOVE);a->Commence();GameToPlay=GAME_SKIRMISH;Check("skirmish traffic remains unchanged",!Campaign_Traffic_Wait(a));GameToPlay=GAME_NORMAL;b->House=HouseClass::As_Pointer(HOUSE_BAD);Check("enemy obstacles never trigger friendly command retention",!Campaign_Traffic_Wait(a));}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);HeadOn(dir,false);HeadOn(dir,true);WakeUp(dir);StationaryYield(dir);Command(dir);InfantryWake(dir);Restrictions(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
